/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    Map parameters = SqlParams::create();

    const str message = "Duplicate records removed from METDUTYROLLVARIANCE.";

    str sqlCode = @"
    ;WITH DuplicateRecords AS
    (
        SELECT *,
               ROW_NUMBER() OVER
               (
                   PARTITION BY
                       LODGEMENT,
                       ITEMID,
                       ORDERNUMBER,
                       ExciseRegisterReferenceId,
                       VersionNumberRegister
                   ORDER BY RecId DESC
               ) AS RN
        FROM METDUTYROLLVARIANCE
    )
    DELETE FROM DuplicateRecords
    WHERE RN > 1;
    ";

    Connection connection = new Connection();
    SqlStatementExecutePermission perm = new SqlStatementExecutePermission(sqlCode);

    perm.assert();

    Statement statement = connection.createStatement();
    statement.executeUpdateWithParameters(sqlCode, parameters);
    statement.close();

    CodeAccessPermission::revertAssert();

    info(message);
}
